(637, 'itIT', 'Scintille di Vita: Isola Proibita', 'Kazure a Valdrakken ti ha sfidato a sconfiggere gli avversari nel combattimento PVP.', 'Accetta missione', '', '', 56647),
(607, 'itIT', 'Scintille di Vita: Thaldraszus', 'Seknar a Valdrakken ti ha sfidato a sconfiggere gli avversari nel combattimento PVP.', 'Accetta missione', '', '', 56647),
(606, 'itIT', 'Scintille di Vita: Vastità Azzurra', 'Keenu a Valdrakken ti ha sfidato a sconfiggere gli avversari nel combattimento PVP.', 'Accetta missione', '', '', 56647),
(605, 'itIT', 'Scintille di Vita: Pianure di Ohn\'ahra', 'Ailith Brezzapetrosa a Valdrakken ti ha sfidato a sconfiggere gli avversari nel combattimento PVP.', 'Accetta missione', '', '', 56647),
(604, 'itIT', 'Scintille di Vita: Sponde del Risveglio', 'Ailith Brezzapetrosa a Valdrakken ti ha sfidato a sconfiggere gli avversari nel combattimento PVP.', 'Accetta missione', '', '', 56647),
(738, 'itIT', 'La guerra interna', 'Viaggia verso Silitus per indagare sul mistero delle visioni apparse in tutta Azeroth.', 'Accetta missione', '', '', 56647),
(737, 'itIT', 'La guerra interna', 'Viaggia verso Silitus per indagare sul mistero delle visioni apparse in tutta Azeroth.', 'Accetta missione', '', '', 56647);
