INSERT INTO `battle_pet_ability_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2435, 'itIT', 'Vampa di Mana', 'Infligge [StandardDamage(1,1,2436)] danni [School()] ogni volta che subisce danni diretti.\n\nDura [duration(1,1)] |4turno:turni;.', 56647),
(2378, 'itIT', 'Raggi di Luce', '|cffffffffProbabilità d\'impatto:|r [StandardAccuracy(1,1)]\n\nInfligge [StandardDamage(1,1)] danni [School()] alla mascotte nemica attiva e [StandardDamage(1,2)] danni [School()] alle mascotte di riserva nemiche. Rigenera [StandardHealing(1,1)] salute a tutti gli alleati.', 56647),
(1369, 'itIT', 'Pungiglione Uncinato', '[StandardAccuracy(1,1)] |cffffffffProbabilità d\'impatto:|r\n\nInfligge istantaneamente [StandardDamage(1,1)] danni [School()] e ha una probabilità del 20% di rendere la mascotte avversaria |cFF1EFF00Avvelenata|r, infliggendo [StandardDamage(1,1,379)] danni [School(379)] aggiuntivi a ogni turno per [duration(1,2)] |4turno:turni;.', 56647);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(3265, 'itIT', 'Davvero il più dignitoso dei musken puzzolenti.', '|cFFFFD200Impresa:|r Nella Botte Piccola...', 56647),
(4517, 'itIT', 'In un miracolo di sogni e desideri, Stoppetto si è svegliato ed è sceso dalla testa di un Coboldo per seguire il proprio cammino.', '|cFFFFD200Impresa:|r Safari di Khaz Algar|n', 56647),
(4581, 'itIT', '', '|cFFFFD200Impresa: |rTour da campione: The War Within|n|cFFFFD200Categoria: |rMondo', 56647),
(4543, 'itIT', 'Questa creatura ombrosa segue Ser Pinnus Mrrgglton sin da quando lui l\'ha incontrata per caso durante una delle sue spedizioni. Essendosi affezionato molto al tenebroso amico, Ser Pinnus non se ne separerà tanto facilmente.', '|cFFFFD200Mercante: |rSer Pinnus Mrrgglton|n|cFFFFD200Zona: |rDornogal|n|cFFFFD200Costo: |r10.000|Hcurrency:2803|h|TInterface\\ICONS\\INV_Misc_ElvenCoins.blp:0|t|h', 56647);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(268268, 'itIT', '', 'Grazie alla Fiamma, ma ne dubito.', 56647),
(259733, 'itIT', '', 'Ora tocca a te.', 56647),
(260378, 'itIT', '', 'Grazie, padre. Speriamo che quel momento non arrivi tanto presto.', 56647),
(260375, 'itIT', 'E quando non ci sarò più, continuerai a regnare con una grazia e una forza che io potrei solo sognare.', '', 56647),
(260374, 'itIT', 'Ma tu non hai più bisogno di me. E sono contento di vedere quanto sei forte.', '', 56647),
(260371, 'itIT', 'Volevo solo proteggerti. E non è stato un buon lavoro, il mio. Siamo in grave pericolo persino ora.', '', 56647),
(260345, 'itIT', '', 'Non posso perdonarti appieno, ma posso comprenderti.', 56647),
(260336, 'itIT', '', 'Ma più invecchio, più Dagran cresce e più capisco cosa vuol dire comandare...', 56647),
(260333, 'itIT', '', 'Ho una mezza idea di ripeterti cosa penso di ciò che hai fatto a me da piccola... e al padre di Dagran.', 56647),
(260303, 'itIT', 'Ma, malgrado me, sei cresciuta con l\'intuito per governare e il cuore per permettere a Dagran di diventare l\'uomo che sarà.', '', 56647),
(260294, 'itIT', 'No, e me lo merito. Ho fatto cose di cui non vado fiero.', '', 56647),
(260287, 'itIT', '', 'Cosa? Accidenti, n-non avrei mai pensato di sentirtelo dire. Va tutto bene?', 56647),
(260283, 'itIT', 'Volevo solo dire che... sono fiero di te.', '', 56647),
(260266, 'itIT', 'Questo lo vedo. Meglio di quanto avrei fatto io con queste... macchine.', '', 56647),
(260265, 'itIT', '', 'Non preoccuparti, padre. Ho tutto sotto controllo.', 56647),
(260264, 'itIT', 'Moira, posso parlarti?', '', 56647),
(263779, 'itIT', 'Grazie, mamma. Io... non so cosa dire, oltre che... non vedo l\'ora di scoprire cosa troveremo... insieme.', '', 56647),
(263778, 'itIT', '', 'Non c\'è nessun altro con cui vorrei irrompere in una città, conoscere nuova gente e saltare in un buco oscuro.', 56647),
(263777, 'itIT', '', 'Sei il futuro del nostro popolo e hai molto da offrire a questo mondo... non lasciare che ti convincano del contrario.', 56647),
(263776, 'itIT', '', 'Ore? Ti ascolterei per giorni. Forse sono di parte perché sei mio figlio, ma hai una mente brillante.', 56647),
(263775, 'itIT', 'Davvero? A volte mi fai delle domande... e se riguardano un argomento che mi entusiasma, posso parlare per ore.', '', 56647),
(263774, 'itIT', '', 'Hai sempre avuto un talento per la storia... e la cultura. Ti vedo già come consigliere.', 56647),
(263773, 'itIT', '', 'Bene. Non volevo metterti in pericolo, ma sono felice che l\'avventura ti faccia sentire a tuo agio.', 56647),
(263772, 'itIT', 'No, mamma. Ho imparato tantissimo qui. Il mondo sembra così nuovo... e antico allo stesso tempo.', '', 56647),
(263771, 'itIT', '', 'Dagran, sei pronto? Non... non devi, se non vuoi. Puoi restare nell\'Archivio, se preferisci.', 56647),
(260591, 'itIT', '', 'Dornogal ha perso il suo protettore e io ho perso... un amico.', 56647),
(260588, 'itIT', '', 'Se non fossimo stati entrambi così cocciuti, non posso fare a meno di pensare che avremmo potuto evitare la sua fine.', 56647),
(260584, 'itIT', '', 'Credevo che non mi avrebbe mai perdonato per averlo lasciato solo, vincolato a Dornogal, ma alla fine...', 56647),
(260582, 'itIT', '', 'La mia logica mi fece allontanare dai Titani. La sua diceva che servivano più che mai.', 56647),
(260580, 'itIT', '', 'Capii cosa stava facendo alla nostra gente. E anche Baelgrim.', 56647),
(260579, 'itIT', '', 'Poi iniziò tutto a... disfarsi. L\'Arteria del Nucleo, l\'Archivio... Mentre raccoglievamo i cocci, arrivò un momento di disperazione.', 56647),
(260578, 'itIT', '', 'Dornogal aveva bisogno di entrambi in egual misura.', 56647),
(260576, 'itIT', '', 'Ma eravamo come due montoni al giogo, che tiravano insieme: lui coi suoi Corvi della Tempesta, io con cava e forgia.', 56647),
(260573, 'itIT', '', 'Confrontavamo i traguardi e gli elogi ricevuti. Facevamo a gara per chi fra noi due era il più favorito dai Titani.', 56647),
(260566, 'itIT', '', 'Io e Baelgrim eravamo rivali. Siamo diventati entrambi Custodi nello stesso periodo.', 56647),
(276521, 'itIT', 'Aprire un Baule Pesante, uno Scrigno Fruttuoso o un Tesoro Nascosto al termine di qualsiasi Scorribanda ti farà ottenere progressi per accedere alle ricompense che abbiamo scoperto.\n\nPiù la Scorribanda è difficile, maggiori saranno i progressi che otterrai!', '', 56647),
(264632, 'itIT', '', 'Ahah! Ahahaha!', 56647),
(263040, 'itIT', 'Quest\'albero è una meraviglia! Era un po\' sciupato, ma non appena è apparso quel granchio, le sue foglie hanno ripreso colore. Molto strano!\n\nSe avessi altri granchi, forse potrei tirargli su il morale. Sembra che agli alberi piacciano!', 'Quest\'albero è una meraviglia! Era un po\' sciupato, ma non appena è apparso quel granchio, le sue foglie hanno ripreso colore. Molto strano!\n\nSe avessi altri granchi, forse potrei tirargli su il morale. Sembra che agli alberi piacciano!', 56647),
(263507, 'itIT', 'ANOMALIA SCONOSCIUTA RILEVATA. ATTIVAZIONE PROGRAMMA DI PURIFICAZIONE.', '', 56647),
(258213, 'itIT', 'Prendi questo portale per Khaz Algar. I sopravvissuti avranno bisogno di aiuto.', '', 56647),
(266134, 'itIT', 'Capito, Zio Brann! Vuoi che provi ad affrontarlo?', '', 56647),
(253394, 'itIT', 'Sono sicuro che il Duca Velhan abbia tutto sotto controllo. È un grande capo!\n\nSai, è grazie alla sua guida che abbiamo perso così pochi dei suoi Arathi alla Caduta di Velhan.', 'Sono sicura che il Duca Velhan abbia tutto sotto controllo. È un grande capo!\n\nSai, è grazie alla sua guida che abbiamo perso così pochi dei suoi Arathi alla Caduta di Velhan.', 56647),
(268948, 'itIT', '', '<risatina divertita>', 56647),
(268647, 'itIT', '', 'I Golem da Guerra sono attivi e di nuovo in produzione.', 56647),
(265314, 'itIT', '', 'Struttura riattivata!', 56647),
(265313, 'itIT', 'Tagliamo la corda, squadra! Riconosco una sconfitta...', '', 56647),
(265081, 'itIT', '', 'Se può farlo con un\'ascesa...', 56647),
(265078, 'itIT', '', 'Ha carpito la mente di Y\'tekhi senza batter ciglio.', 56647),
(265077, 'itIT', '', 'Fuori! Ora!', 56647),
(263478, 'itIT', '', 'È completa.', 56647),
(263476, 'itIT', '', 'La tua ascensione...', 56647),
(260586, 'itIT', '', 'Va\', Zeta-Zeta!', 56647),
(260581, 'itIT', '', 'Intendi così?', 56647),
(260577, 'itIT', 'Dovevate portarvi degli amici un po\' più grossi.', '', 56647),
(261892, 'itIT', '', 'Abbiamo molto lavoro da fare.', 56647),
(261891, 'itIT', 'E adesso, Lufsela?', '', 56647),
(261890, 'itIT', '', 'Hanno deciso di aiutarci per loro scelta.', 56647),
(261889, 'itIT', '', 'Non è solo la mia. È anche la loro.', 56647),
(261888, 'itIT', 'Bene. I Corvi della Tempesta hanno udito la tua chiamata.', '', 56647),
(261884, 'itIT', 'Chiamali e risponderanno.', '', 56647),
(261883, 'itIT', 'Lufsela, i Corvi della Tempesta sanno le tue intenzioni. Concentrati.', '', 56647),
(261881, 'itIT', 'Se lui ha disobbedito ai Titani, puoi farlo anche tu!', '', 56647),
(261880, 'itIT', 'Baelgrim ha evocato i Corvi della Tempesta da solo.', '', 56647),
(261878, 'itIT', '', 'Non ci riesco. I Titani...', 56647),
(263833, 'itIT', '', '<borbotta>', 56647),
(261968, 'itIT', 'Svincolati!', '', 56647),
(261967, 'itIT', 'Io, Custode del Concilio di Dornogal, dichiaro che siamo tutti...', '', 56647),
(261966, 'itIT', 'Chi vuole avere l\'onore?', '', 56647),
(261958, 'itIT', 'Dove gli Editti furono scritti.', '', 56647),
(261957, 'itIT', 'Allora è giusto che accada qui... dove tutto è iniziato...', '', 56647),
(261956, 'itIT', '', 'E per farlo dobbiamo rinunciare agli Editti... per sempre.', 56647),
(261955, 'itIT', '', 'Sì. Dobbiamo aiutare i nostri nuovi alleati.', 56647),
(261954, 'itIT', 'Allora siamo d\'accordo?', '', 56647),
(252684, 'itIT', 'Eh? Ci conosciamo?\n\nNo? Bene. La mia memoria non è più quella di un tempo.\n\nSono Korgran, sorvegliante dell\'Altura del Cordoglio, un luogo di preparazione per gli Svincolati che si apprestano allo spegnimento finale.\n\nChi viene qui nei suoi ultimi istanti lo fa per spezzare il ciclo dei Titani ed essere ricordato come lo Svincolato che ha deciso d\'essere.\n\nA meno che la tua specie non subisca una stasi come la nostra, non so come posso aiutarti.', '', 56647),
(261480, 'itIT', 'Hai visto questi nuovi tomi, zio Brann? Devono venire dalla biblioteca di Drenden.', '', 56647),
(259252, 'itIT', 'Oh! Salve. Sei qui per parlare con lo zio Brann?', '', 56647),
(251198, 'itIT', 'Resterò incollato a te e allo Zio Brann. Non vedo l\'ora di imparare ogni cosa di questo posto!', '', 56647),
(261676, 'itIT', '', 'Salute a te. Devo ammettere che sono piuttosto emozionata di vedere Khaz Algar. Ci sarà davvero molto da esplorare!', 56647),
(275557, 'itIT', '', 'Grim Batol non è mai stato un posto piacevole per i draghi, quindi non lo conosco bene.\n\nMa se ci vuoi andare per sconfiggere nemici terribili e conquistare i loro tesori, allora ti faccio i miei migliori auguri.\n\nPrendi il portale dai Flussi Temporali per le Alture del Crepuscolo, quindi dirigiti verso ovest fino all\'entrata annidata sul fianco della montagna.', 56647),
(275556, 'itIT', '', 'Ovviamente si trova a Boralus. Cerca lungo i moli, sotto il Mercato di Ventosaldo.\n\nA meno che tu non sia un membro dell\'Orda, nel qual caso l\'entrata più sicura è al Porto del Saccheggio.\n\nInizia prendendo il portale dai Flussi Temporali per la Baia di Tiragarde, quindi vai verso nord e fai attenzione a non incrociare quelli che ti ucciderebbero a vista.', 56647),
(275555, 'itIT', '', 'Scia\" è una parola buffa. A volte è la strada che devi seguire per andare da qualche parte, altre volte è il segno che lasci dietro di te dopo che te ne sei andato.\n\n<Lindormi fa una breve pausa per osservare la tua reazione.>\n\nComunque, prendi il portale dai Flussi Temporali per il Bastione e dirigiti a sud-ovest. L\'entrata è sul lato del Tempio del Coraggio che non è ancora stato completamente distrutto.', 56647),
(275554, 'itIT', '', 'Tirna Falcis è il posto perfetto in cui perdersi. Potresti perderti anche cercando di raggiungerla!\n\nPrendi il portale dai Flussi Temporali per Selvarden, quindi dirigiti verso ovest e cerca l\'entrata, che è ben nascosta tra le radici.', 56647),
(269791, 'itIT', '\"...su ali di fulmine.\"', '', 56647),
(269790, 'itIT', '', '\"...su ali di fulmine.\"', 56647),
(268067, 'itIT', 'Riesci a crederci, $n? Pensa a tutta la storia che è sepolta qui!', '', 56647),
(266394, 'itIT', 'Se $glo straniero:la straniera; può proseguire, noi non dobbiamo essere da meno. L\'imperatore esige che ci spingiamo oltre i limiti dei nostri stessi nemici.', '', 56647),
(266392, 'itIT', 'La Fiamma Sacra ci sosterrà, fratello. Lascia che $gil pagano:la pagana; attiri la furia dei Kobyss. Poi li colpiremo sul fianco scoperto.', '', 56647),
(266390, 'itIT', 'Ti prego di scusare Sybastian, $gmio nuovo amico:mia nuova amica;. Non saremmo mai arrivati fin qui senza il tuo aiuto.', 'Ti prego di scusare Sybastian, $gmio nuovo amico:mia nuova amica;. Non saremmo mai arrivati fin qui senza il tuo aiuto.', 56647),
(266389, 'itIT', 'La tua disciplina in battaglia è sorprendente, fratello. $gQuesto straniero:Questa straniera; farebbe bene a guardare e imparare.', '', 56647),
(261758, 'itIT', '<Anduin volge lo sguardo verso di te.>\n\n$n. Il tuo aiuto è stato fondamentale quaggiù, come sempre. Come ci riesci? \n\nSin dalle Terretetre io...\n\nFaccio fatica.', '', 56647),
(261247, 'itIT', '<Anduin volge lo sguardo verso di te.>\n\n$n. Il tuo aiuto è stato fondamentale quaggiù, come sempre. Come ci riesci? \n\nCome fai a guardarmi in faccia dopo tutto quello che è successo... quello che ti ho fatto?\n\nHo provato a ucciderti.', '', 56647),
(260534, 'itIT', 'Quando accadrà?', '', 56647),
(260468, 'itIT', 'Quanto è stata qui Dornogal?', '', 56647),
(260045, 'itIT', 'Come dici?', '', 56647),
(259965, 'itIT', 'Si torna al lavoro... o forse no.', '', 56647),
(258826, 'itIT', 'Ehilà! Ti interessa una caccia al tesoro? Ma certo che t\'interessa.\n\nHo una lista di oggetti smarriti... ehm, di svariati oggetti sparsi per questa caverna! Il primo che riuscirà a riportarmeli tutti vincerà questo tesoro!\n\nE ci aggiungo anche un cristallo che ti aiuterà a nuotare più rapidamente. Che affarone!', '', 56647),
(258555, 'itIT', '', '<Vokgret beve un sorso del suo Idromele Cinereo prima di guardare verso di te>\n\nTrovare il tuo opale liquido richiederà tempo, mio prezioso sassolino. \n\nQuindi, mentre le mie talpe in giro per il mercato fiutano ciò che cerchi, gradirei che mettessimo a frutto la tua intraprendenza.', 56647),
(256097, 'itIT', '', 'Salve! Felice di conoscerti!\n\nIo sono Tharessa, la nuova apprendista della Spedizione Algari di Rannan.\n\nAnche se... sai com\'è.\n\nMi interessa molto la tecnologia dei Titani, e Rannan e Tuberros sono famosi per essersi occupati di \"quella roba\", come la chiama Rannan. Spero davvero di poterla vedere più da vicino!\n\nE a quanto pare, ci riuscirò! Anche se c\'è voluto un disastro aereo per farcela...', 56647),
(266645, 'itIT', 'Brann? Be\', dev\'essere da qualche parte con gli altri esploratori. \n\nDobbiamo muoverci, $gcampione:campionessa;. Riesco a sentire le ferite di Azeroth che chiedono aiuto.', '', 56647),
(266491, 'itIT', '', 'Tu è $gbuon amico:buona amica; di Coboldi, $n. Grazie.', 56647),
(254492, 'itIT', 'Come va, $gamico:amica;?', 'Come va, $gamico:amica;?', 56647),
(252740, 'itIT', 'Guardate e nascondetevi, schiavi. Non ci saranno interruzioni nel Giorno dell\'Ascensione.', 'Guardate e nascondetevi, schiavi. Non ci saranno interruzioni nel Giorno dell\'Ascensione.', 56647),
(251935, 'itIT', 'Dobbiamo parlare in fretta. Troppo veleno nell\'aria.\n\nPrendi le Scarpe da Schianto. Usale per riattivare i purificatori rotti e sui Coboldi uccisi per prendere ingranaggi. Prendi tutti gli ingranaggi, salva l\'Acquedotto.\n\nVai.', '', 56647),
(261702, 'itIT', '', 'È giunto il momento di scoprire chi siamo.', 56647),
(261700, 'itIT', '', 'Azeroth sta crescendo e noi dobbiamo farlo con essa.', 56647),
(261701, 'itIT', '', 'Dobbiamo accogliere il richiamo del cambiamento.', 56647),
(261699, 'itIT', '', 'Le tradizioni stagnanti ci hanno quasi rovinato.', 56647),
(261696, 'itIT', '', 'Prima del sacrificio di Magni, noi Terrigeni eravamo vincolati da uno scopo innato.', 56647),
(252793, 'itIT', 'The Weaver bids you welcome.', 'La Tessitrice vi dà il benvenuto.', 56647),
(252791, 'itIT', 'Scurry on, little scarab!', 'Corri, piccolo scarabeo!', 56647),
(256695, 'itIT', '', 'Forse vuoi celare il tuo stesso tradimento! Dopo averli dilaniati, mi prenderò anche la tua testa.', 56647),
(256694, 'itIT', 'Schiaccerò questi ribelli in nome della Regina Ansurek.', '', 56647),
(256691, 'itIT', 'L\'unica cosa che porterai alla luce sarà la tua debolezza.', '', 56647),
(256690, 'itIT', '', 'I cospiratori sono qui! Dopo averli uccisi porterò alla luce il traditore che si annida tra noi.', 56647),
(266867, 'itIT', 'Se trovi qualcosa, portala via da qui. Io me ne lavo gli artigli.', 'Se trovi qualcosa, portala via da qui. Io me ne lavo gli artigli.', 56647),
(260896, 'itIT', '', 'Ombra penetrante.', 56647),
(260892, 'itIT', '', 'Vortice colloso.', 56647),
(260891, 'itIT', '', 'Detonazione viscosa.', 56647),
(260875, 'itIT', '', 'Sforzarsi è inutile.', 56647),
(260874, 'itIT', '', 'In trappola.', 56647),
(260838, 'itIT', 'Lo sciame deve nutrirsi.', '', 56647),
(260837, 'itIT', 'Mi scateno.', '', 56647),
(260836, 'itIT', 'Massacro.', '', 56647),
(260835, 'itIT', 'Massacro imminente.', '', 56647),
(260834, 'itIT', 'Inarrestabile.', '', 56647),
(260822, 'itIT', '', 'Le vostre vite sono condannate!', 56647),
(260821, 'itIT', 'Avrò i vostri teschi!', '', 56647),
(261912, 'itIT', 'Sotto terra, miei soldati!', '', 56647),
(254365, 'itIT', '', 'Quando quel Dagran si interessa a qualcosa, non c\'è modo di fermarlo, eh?\n\nCome dicevo, Taelloch è un importante avamposto minerario. Era noto a tutti per essere efficiente come una macchina ben oliata. Conosco il Caposquadra, Kol Bruncrag, da un sacco di tempo, ma è passato un bel po\' dall\'ultima volta che abbiamo parlato.\n\nMi serve sapere perché la produzione di minerali si è fermata. Anche se il Gran Oratore preferirebbe che non lo scoprissi. Probabilmente ha mandato i suoi investigatori, ma dovremmo fare da noi.', 56647),
(271002, 'itIT', 'I Terrigeni sulla superficie del Settore AR-938 hanno affrontato delle difficoltà di recente.\n\nDopo lo schianto degli stranieri sulle coste, la loro fortezza, Dornogal, è stata attaccata dai Nerubiani. Gli stranieri e i Cavalcatempesta sono riusciti a respingere gli invasori, ma l\'Arteria del Nucleo è rimasta gravemente danneggiata.\n\nCon l\'aiuto degli stranieri, i gruppi di Terrigeni designati come Svincolati (precedentemente conosciuti come Legapietra) e gli Ossequenti (quelli ancora fedeli ai Titani) hanno unito le forze per difendere la superficie, respingere i Nerubiani e dare inizio alla ricostruzione dell\'Arteria del Nucleo.\n\nDurante questi eventi, i Cavalcatempesta hanno subito delle perdite ingenti, inclusa la scomparsa del Guardiatempesta Baelgrim. Tuttavia, è stato possibile ripristinare l\'accesso dall\'Arteria del Nucleo a Gundargaz e agli Oratori delle Macchine.\n\nI lavori di riparazione dell\'Arteria del Nucleo sono ancora in corso.', '', 56647),
(270198, 'itIT', 'Il Servitore del Trasformatorio percepisce i tuoi feromoni e si tiene a debita distanza.', '', 56647),
(266936, 'itIT', '', 'Solo che tu e Turalyon siete molto simili: audaci in battaglia e timidi in faccende di cuore.', 56647),
(265279, 'itIT', 'Le sorti della battaglia stanno per cambiare!', '', 56647),
(265155, 'itIT', '', 'La tua sopravvivenza non era necessaria.', 56647),
(263196, 'itIT', '', 'Il Gran Oratore ci ha governato sin da tempi immemorabili... ma non è più uno di noi.', 56647),
(262604, 'itIT', '', 'Protocollo sismico attivato.', 56647),
(262333, 'itIT', 'Scommetto che possiamo rimbalzare su quei funghetti.', '', 56647),
(261918, 'itIT', '', 'Intrusi? Ci hai visto cadere dal cielo e combattere per difenderci!', 56647),
(259785, 'itIT', 'Ora dobbiamo sbarazzarci di quell\'affare. Sembra che i Kobyss lo trattengano usando quell\'esca laggiù.', '', 56647),
(259762, 'itIT', '', 'Arrenditi alla notte.', 56647),
(256027, 'itIT', '', 'Continuavi a ignorare il tuo guaritore! Come potevo resistere a un\'occasione così ghiotta?!?', 56647),
(256024, 'itIT', 'E io che stavo cercando di capire come far avanzare il mio fante senza perderlo! E così lasci scoperto il tuo cavaliere, eh, Faerin? Un vero azzardo.', '', 56647),
(255118, 'itIT', 'Questa città è mozzafiato. Vedere ciò che hanno costruito gli Arathi qui in così poco tempo è incredibile.\n\nSe si pensa che, mentre accadeva tutto questo, noi stavamo combattendo la Legione, poi la Quarta Guerra e poi...\n\nBe\', è un vero spettacolo.', '', 56647),
(254822, 'itIT', 'Domanda più che legittima, $R. Sono un Risvegliatore. Il mio compito è entrare in questi vecchi luoghi, o quelli risvegliati di recente, e assicurarmi che tutto funzioni a dovere. Pensa alle Profondità Risonanti come se fossero un grande gigante addormentato. Io faccio in modo di prendermene cura!\n\nProteggimi mentre mi concentro sul rituale, e cerca di assorbire quanta più energia nascente possibile dalla Macchina! Se riusciamo a caricarci abbastanza, dovremmo riuscire a completare il rituale...', '', 56647),
(268527, 'itIT', 'Non siete l\'unica, Prelata. In questo stato, il sembiante di Beledar è presagio di conflitto e sventura.', '', 56647),
(267619, 'itIT', 'E io ci lascerò tutte le lettere che troverò per te e Kralla, Blu.', '', 56647),
(266121, 'itIT', '<Dagran si lancia in una lunga dissertazione sulla cera dei Coboldi, la sua provenienza e il suo impiego. È evidente come tutte queste nozioni provengano esclusivamente dalle ricerche compiute a Forgiardente e Khaz Algar, e non da un\'esperienza diretta.>', '', 56647),
(265612, 'itIT', 'Avevo sentito parlare degli Arathi. Quando ero... cioè, ero curioso.', '', 56647),
(265403, 'itIT', 'Che cosa stai cercando di dirci?', '', 56647),
(265214, 'itIT', 'Affascinante...', '', 56647),
(264962, 'itIT', 'Ma se fosse vero, vorrei vederlo con i miei occhi. Potrebbero rivelarsi nostri alleati nella lotta contro Xal\'atath.', '', 56647),
(264692, 'itIT', '$n! Sono riuscito a liberare alcune Api di Cenere.', '', 56647),
(264131, 'itIT', 'Sembrano tutti su di giri, non trovi? Non riesco a capire perché.\n\nOh, giusto. Tutte quelle orribili visioni di distruzione. Il motivo per cui Dalaran è stata teletrasportata a Khaz Algar. Ora ricordo.', '', 56647),
(264128, 'itIT', 'Ti preoccupano i pericoli che si celano a Khaz Algar? Niente paura. Dopotutto, a guardarti le spalle c\'è il fantastico Reno Jackson!', '', 56647),
(264108, 'itIT', 'Tuttavia, eliminare Xal\'atath non basterà a salvare la nostra gente.  È Ansurek l\'artefice della nostra rovina.', '', 56647),
(262984, 'itIT', 'L\'Aralda mi ha sussurrato del tuo arrivo...', '', 56647),
(262611, 'itIT', '', 'Disattivazione si-si-si-si-sistemi... in corso...', 56647),
(261944, 'itIT', 'Non posso. Per questo devo farlo io. Tu devi guidare i Terrigeni.', '', 56647),
(261934, 'itIT', 'Ho solo sentito storie delle loro gesta eroiche... È un segno dei Titani!', '', 56647),
(261921, 'itIT', 'Quello che vi serve non importa.', '', 56647),
(261418, 'itIT', '', 'Ahem! Ho detto... hanno ucciso tutti!', 56647),
(261128, 'itIT', '', 'Il Grande Innalzatore Etak\'kaht, il Magistrato delle Alte Fosse, ha le conoscenze giuste per garantirmi l\'Ascensione.\n\nAmmesso che riesca a guadagnarmi il suo favore.\n\n<Tx\'itk strizza tutti i suoi occhi con una leggera irritazione.>\n\n...Ammesso che riusciamo a trovarlo.', 56647),
(260471, 'itIT', 'Potresti farmi una stima?', '', 56647),
(260469, 'itIT', '', 'Non si sa. Il nostro Archivio potrebbe avere questa informazione, ma, come ho detto, non funziona.', 56647),
(260334, 'itIT', 'Ho controllato i cristalli nelle loro Guardafiamme. Non è Azerite, ma è simile, mi fa pensare a un collegamento.', '', 56647),
(260299, 'itIT', '', 'Hanno tutti una storia così. Ricordo che una volta ho trovato una caverna con...', 56647),
(260176, 'itIT', 'Ma certo! Immagino che la tua memoria sia come la mia. Un po\' arrugginita e affaticata, dopo qualche migliaio di anni...', '', 56647),
(260092, 'itIT', '', 'Lascerò aumentare le vostre taglie prima di riscuotere. Fino ad allora... guardatevi le spalle.', 56647),
(260028, 'itIT', 'Sempre avanti. Verso la prossima avventura.', '', 56647),
(260019, 'itIT', '', 'Dunque, ora che sei... cambiato... come ti senti?', 56647),
(259046, 'itIT', 'Non brancolare nel buio.', 'Non brancolare nel buio.', 56647),
(258553, 'itIT', '<La Tessispia solleva la nota mentre la esamini.>\n\nCi sono diversi esperimenti che stanno devastando il Sottoforte. Distruggili prima che riescano a fuggire.\n\nNascosti qui vicino ci sono dei feromoni esplosivi in grado di fermarli. Ma prima di tutto, dovrai mascherare il tuo odore. Per farlo ti ho fornito dei feromoni.\n\nRecupera i dispositivi e poni fine alla vita di queste povere creature.\n\n--La Tessitrice', '', 56647),
(258479, 'itIT', 'Ah! Sì! Scappa via!', 'Sì! Scappa via!', 56647),
(258194, 'itIT', 'Tutti voi! Tornate ai vostri doveri. Ora!', '', 56647),
(258037, 'itIT', 'Non fraintendermi. Dobbiamo andare subito a Khaz Algar, ma ammetto di essere ancora stanco. \n\nAzeroth sa darti delle belle botte quando vuole.', '', 56647),
(258035, 'itIT', 'Quindi il nostro destino ci aspetta a Khaz Algar. Chissà cosa troveremo? Oltre a fuoco e fumo, intendo.', '', 56647),
(258010, 'itIT', 'Nonno ne ha passate di molto peggio. So che si sveglierà presto.\n\nDeve farlo...', '', 56647),
(258006, 'itIT', 'Non credo che dovremmo incolpare Azeroth per ciò che è successo. Magni sapeva quali erano i rischi che correva cercando di comunicare con lei con una tale riluttanza nel cuore.\n\nOra possiamo solo sperare che sia almeno riuscito a sentire il suo messaggio.', '', 56647),
(257697, 'itIT', 'Si sono teletrasportati?!? Finalmente una svolta!', 'Si sono teletrasportati?!? Finalmente una svolta!', 56647),
(257511, 'itIT', '', 'Olbarig, dove sei? Abbiamo bisogno di te...', 56647),
(255510, 'itIT', '', 'Un attimo! Non sappiamo cosa ci sia là sotto! I rinforzi stanno arrivando, dovremmo aspettare...', 56647),
(254629, 'itIT', '', 'Questa... ombra! È troppo!', 56647),
(253162, 'itIT', 'Non possiamo invitare nessun altro.', '', 56647),
(253151, 'itIT', 'Non ho abbastanza furia.', '', 56647),
(252126, 'itIT', 'Sono felice che il nonno stia bene ora. Non abbiamo passato tanto tempo insieme, e solo il pensiero di...\n\nMa ora è tutto a posto! Sembra si sia ripreso del tutto.', '', 56647),
(268542, 'itIT', '', 'Abbiamo recuperato le Gemme del Ricordo. Tuttavia, dobbiamo continuare per ripulire la zona dall\'attuale minaccia dei Nerubiani. Anche se le loro ragnatele sono ovunque...\n\nModificherò il dispositivo in modo che possa distruggere le ragnatele. Usalo per aprirci la strada.', 56647),
(268257, 'itIT', 'È colpa di Temper e la sua solita lentezza.', '', 56647),
(268256, 'itIT', 'Ti hanno sporcato la tunica perché hai iniziato prima che il difensore fosse pronto.', '', 56647),
(268043, 'itIT', '', 'Sorella, tutto a posto?', 56647),
(267317, 'itIT', '', '<La precedente timidezza di Tara è svanita, e ora impugna allegramente un cucchiaio agitandolo come fosse una spada.>\n\nDa grande, voglio diventare una Terrigena! La mamma dice che sono duri come la roccia e che dentro di loro hanno delle gemme. \n\nHo già provato a mangiare una gemma, ma non è stato facile. Quindi ho deciso di andarci piano all\'inizio, di frantumare le gemme prima, così sarà tutto più semplice!', 56647),
(265656, 'itIT', '', 'Questo... era un favore che una cavaliera mi aveva chiesto prima di partire per la spedizione.', 56647),
(265652, 'itIT', 'Quest\'immagine raffigura la Ballata di Artiglio di Fiamma, una leggendaria lince da guerra che si gettò in una nave in fiamme per salvare il suo cavaliere.', '', 56647),
(265609, 'itIT', '', 'È un piacere vederti. Seguo le tracce di questo mostro sin da quando è sbucato dalla sua tana.', 56647),
(265317, 'itIT', 'Wow, ti ha detto che sono un genio? Sono cose come questa che mi accendono la lampada, se capisci cosa intendo.', '', 56647),
(264561, 'itIT', '', 'La creatura è fuggita dalla sua Regina con la coda tra le gambe. Senza dubbio le riferirà delle tue imprese.', 56647),
(264549, 'itIT', '', 'Fortunatamente, mia figlia e i suoi bambini sono salvi. Hai indebolito il comandante e purificato la mia dimora. Grazie.', 56647),
(262945, 'itIT', 'Ci avventurammo per mari in tempesta. Mai nella mia vita avevo visto onde così alte o sentito un vento così forte! Avevo paura che le nostre navi non avrebbero resistito!', 'Ci avventurammo per mari in tempesta. Mai nella mia vita avevo visto onde così alte o sentito un vento così forte! Avevo paura che le nostre navi non avrebbero resistito!', 56647),
(262812, 'itIT', 'Entra!', 'Entra!', 56647),
(262440, 'itIT', 'È tempo di stuzzicare l\'alveare!', '', 56647),
(262197, 'itIT', 'Non saranno un pasto prelibato, ma se ne prendi un po\' e le metti in un barattolo, sono un\'ottima fonte di luce.\n\nUna volta, mentre frugavo tra delle sterpaglie, una grossa Scintillucciola si è avvicinata alla mia luce! Mi ha seguito per un po\', come fosse un animaletto domestico. Una creatura gentile, voleva solo svolazzarmi intorno e brillare della sua luce colorata.', '', 56647),
(261385, 'itIT', 'La marionetta Terrigena è bloccata in uno stato di disperazione, con dei dettagli paragonabili solo alla maestria d\'artigianato che contraddistingue i Terrigeni veri.\n\nLa consistenza della pietra di quest\'opera sembra identica a quella di un vero Terrigeno.', 'La marionetta Terrigena è bloccata in uno stato di disperazione, con dei dettagli paragonabili solo alla maestria d\'artigianato che contraddistingue i Terrigeni veri.\n\nLa consistenza della pietra di quest\'opera sembra identica a quella di un vero Terrigeno.', 56647),
(261292, 'itIT', 'Non restare lì!', '', 56647),
(260817, 'itIT', 'Ti do il benvenuto, $R.\n\nMolto tempo fa, il Custode del Concilio Merrix mi ha nominato arredatore di Dornogal.\n\nIl mio solenne compito consiste nel mantenere l\'armonia estetica della nostra città. Con ogni nuovo ciclo, infondo diligentemente stile e bellezza nelle strade di Dornogal, decorandole con un delicato tocco di eleganza e fascino funzionale degno della nostra nobile tradizione.\n\nIn quanto arredatore ufficiale, ho giurato di rispettare la volontà di Merrix e di assicurarmi che Dornogal resti un faro di bellezza e meraviglia per molti cicli a venire.\n\nCome posso aiutarti?', '', 56647),
(259422, 'itIT', '', 'Grazie! Prendi questi stivali e fa\' vedere ai Kobyss che non resteremo a guardare mentre distruggono i nostri villaggi.', 56647),
(259414, 'itIT', '', 'Ho inseguito questo gruppo di Kobyss nella Voragine dopo che avevano saccheggiato un villaggio e le sue reliquie.\n\nPurtroppo, sono più un\'inventrice che una combattente. È solo grazie all\'adrenalina che sono arrivata fin qui. Ho un\'invenzione che potrebbe aiutarti, però.\n\nTi autorizzo a usare i miei stivali leggeri. La loro magia ti proietterà in alto nell\'aria in modo che tu possa abbatterti in picchiata su nemici ignari. Dovrebbero esserti utili a sconfiggere i Kobyss qui sotto.', 56647),
(257935, 'itIT', '', 'I Nerubiani usano gli Skardyn per rapire gli Oratori delle Macchine.\n\nPiano: prendi questo dispositivo. Attirerà gli Skardyn verso un altro luogo. Usalo per salvare gli altri Oratori. \n\nQuesto piano è... sperimentale. Non adatto a me. Io rimarrò qui.', 56647),
(256314, 'itIT', '', 'Le Linci Imperiali possono essere davvero testarde. Il mio Guizzo si lascia cavalcare solo da me. Quando è di cattivo umore, può capitare di dovermi fare a piedi l\'ultimo tratto per ultimare una consegna.\n\nMa quando si mette in marcia, non c\'è niente che lo superi in velocità, se non un\'aeronave. E non mi farei guardare le spalle da nessun altro lungo la strada.', 56647),
(255997, 'itIT', 'Sembra che una visita si rivelerebbe un viaggio interessante.', '', 56647),
(255898, 'itIT', '<Kiera canticchia mentre cucina, sorridendo. La padella emana un odore di cipolle e aglio.>', '<Kiera canticchia mentre cucina, sorridendo. La padella emana un odore di cipolle e aglio.>', 56647),
(253535, 'itIT', '', 'Dannazione... se n\'è andata. Chiunque ci abbia salvato prima non è amica dei Nerubiani. Cercala. Io porterò tutti in salvo.', 56647),
(248952, 'itIT', 'Si salta, a quanto pare!', '', 56647);
