INSERT INTO `chr_classes_locale` (`ID`, `locale`, `Name_lang`, `NameMale_lang`, `NameFemale_lang`, `Description_lang`, `RoleInfoString_lang`, `DisabledString_lang`, `HyphenatedNameMale_lang`, `HyphenatedNameFemale_lang`, `VerifiedBuild`) VALUES
(4, 'itIT', 'Ladro', 'Ladro', 'Ladra', 'I Ladri sono spesso impiegati come assassini o esploratori, anche se in genere sono tipi piuttosto solitari. Possono aggirare silenziosamente i propri nemici o attaccarli alle spalle, cercando di ucciderli rapidamente.', 'Ruolo: |cffffffffAssaltatore in mischia|r', 'Devi scegliere una razza diversa\nper giocare questa classe.', 'Ladro', 'Ladra', 56647);
