INSERT INTO `chr_races_locale` (`ID`, `locale`, `Name_lang`, `NameFemale_lang`, `NameLowercase_lang`, `NameFemaleLowercase_lang`, `LoreName_lang`, `LoreNameFemale_lang`, `LoreNameLower_lang`, `LoreNameLowerFemale_lang`, `LoreDescription_lang`, `ShortName_lang`, `ShortNameFemale_lang`, `ShortNameLower_lang`, `ShortNameLowerFemale_lang`, `VerifiedBuild`) VALUES
(85, 'itIT', 'Terrigeno', 'Terrigena', 'Terrigeno', 'Terrigena', 'Terrigeno', '', 'Terrigeno', '', 'Appena liberati dagli Editti che li vincolavano, i nuovi Terrigeni si avventurano con sconfinata curiosità per esplorare il mondo e unirsi all\'Alleanza.', 'Terrigeno', '', 'Terrigeno', '', 56647),
(84, 'itIT', 'Terrigeno', 'Terrigena', 'Terrigeno', 'Terrigena', 'Terrigeno', '', 'Terrigeno', '', 'Appena liberati dagli editti che li vincolavano, i nuovi Terrigeni si avventurano con sconfinata curiosità per esplorare il mondo e unirsi all\'Orda.', 'Terrigeno', '', 'Terrigeno', '', 56647),
(36, 'itIT', 'Orco Mag\'har', 'Orchessa Mag\'har', 'Orco', 'Orchessa', 'Mag\'har', '', 'Mag\'har', '', 'Un tempo parte di clan rivali, ora gli Orchi incorrotti di Draenor si sono riuniti nei feroci Mag\'har.', 'Orco', '', 'Orco', '', 56647);
