INSERT INTO `faction_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2640, 'itIT', 'Brann Barbabronzea', 'Compagno Fidato delle Scorribande', 56647),
(2600, 'itIT', 'Fili Recisi', 'Il tumultuoso regno della Regina Ansurek non è privo di detrattori. I Fili Recisi agiscono scaltramente e con discrezione dietro le quinte per disfare dall\'interno l\'arazzo del dominio di Ansurek.', 56647),
(2596, 'itIT', 'Fili Recisi (Eccellenza)', 'Il tumultuoso regno della Regina Ansurek non è privo di detrattori. I Fili Recisi agiscono scaltramente e con discrezione dietro le quinte per disfare dall\'interno l\'arazzo del dominio di Ansurek.', 56647),
(2606, 'itIT', 'Alte Fosse', 'Controlla il comportamento delle creature nelle Alte Fosse della Città dei Fili.', 56647),
(2649, 'itIT', 'Generale (Eccellenza)', 'Un tempo il capo militare più conosciuto di Azj-Kahet, Anub\'azal ha visto il suo prestigio scemare in favore di uno degli amati Ascesi di Ansurek. Un atto inaccettabile.', 56647),
(2648, 'itIT', 'Tessitrice (Eccellenza)', 'Un tempo Tessitrice Reale, ora la Vedova Arak\'nai osserva attentamente la sua vecchia dimora con occhio critico. Con una rete di Tessispie e informatori a sua disposizione, ben poco sfugge al suo sguardo.', 56647),
(2647, 'itIT', 'Visir (Eccellenza)', 'Arroccato nella posizione più pericolosa fra tutte, l\'Esecutore Nizrek passa i suoi giorni nelle vesti del più fedele consigliere della Regina Ansurek. Fortunatamente, Ansurek non ha ancora scoperto che il resto del suo tempo lo trascorre a tentare di deporre il suo regno.', 56647),
(2607, 'itIT', 'Il Visir', 'Arroccato nella posizione più pericolosa fra tutte, l\'Esecutore Nizrek passa i suoi giorni nelle vesti del più fedele consigliere della Regina Ansurek. Fortunatamente, Ansurek non ha ancora scoperto che il resto del suo tempo lo trascorre a tentare di deporre il suo regno.', 56647),
(2605, 'itIT', 'Il Generale', 'Un tempo il capo militare più conosciuto di Azj-Kahet, Anub\'azal ha visto il suo prestigio scemare in favore di uno degli amati Ascesi di Ansurek. Un atto inaccettabile.', 56647),
(2601, 'itIT', 'La Tessitrice', 'Un tempo Tessitrice Reale, ora la Vedova Arak\'nai osserva attentamente la sua vecchia dimora con occhio critico. Con una rete di Tessispie e informatori a sua disposizione, ben poco sfugge al suo sguardo.', 56647);
