INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(776, 'itIT', 'Rylak Spettrale Rapido', '|cFFFFD200Oggetto del passato|r', 'Anche i morti hanno bisogno di volare rapidamente ogni tanto.', 56647),
(2188, 'itIT', 'Kah, Leggenda delle Profondità', '|cFFFFD200Impresa: |rPesca sotterranea|n|cFFFFD200Categoria: |rPesca', '', 56647),
(2218, 'itIT', 'Vilpipistrello del Gladiatore Forgiato', '|cFFFFD200Impresa:|r Gladiatore: Stagione 1 di The War Within|n|cFFFFD200Categoria:|r PvP', 'Risvegliato dalle caverne per andare in battaglia, corazzato fino all\'osso.', 56647),
(2159, 'itIT', 'Unità di Difesa della Macchina 1-11', '|cFFFFD200Tesoro: |rCassa Risvegliata|n|cFFFFD200Zona: |rProfondità Risonanti', 'Una delle tante meccanotute progettate per proteggere la Macchina. Dopo anni di fedele servizio, non è più adatta al combattimento. Però come mezzo di trasporto fa un figurone.', 56647),
(2209, 'itIT', 'Grugnofango Cremisi', '|cFFFFD200Mercante: |rScioglicera Squick|n|cFFFFD200Zona: |rProfondità Risonanti|n|cFFFFD200Costo: |r8.125|Hcurrency:2815|h|TInterface\\ICONS\\SPELL_AZERITE_ESSENCE14.BLP:0|t|h', 'Usate di frequente dai Coboldi come cavalcature. L\'Adunanza delle Profondità ha deciso di concederti una delle sue talpe grugnofango più fedeli.', 56647);
